export const meta = {
  "slug": "phosphor-arrow-u-up-right",
  "family": "phosphor",
  "name": "arrow-u-up-right",
  "category": "Navigation",
  "motion": "slideUp",
  "component": "createPhosphorArrowUUpRightIcon"
};

export function createPhosphorArrowUUpRightIcon(root, options = {}) {
  let current = { ...options };
  const render = () => {
    root.innerHTML = renderSetIcon(definition, current);
  };
  render();
  const controller = bindSetIcon(root, definition, () => current);
  return {
    play: controller.play,
    reset: controller.reset,
    destroy: controller.destroy,
    update(next = {}) {
      current = { ...current, ...next };
      render();
    },
    get observed() {
      return controller.observed;
    },
  };
}
